{"id":"5","number":5,"category":"Integrar","difficulty_level":4,"primary":"INTER-VLAN ROUTING","related":["MAC","Frame","IPv4"],"title":"Dois frames, um pacote","scenario":"A=AA · gateway VLAN10=R10 · gateway VLAN20=R20 · B=BB","instruction":"Monte os dois frames e mantenha o destino IP.","fields":[field("f1","Frame VLAN10",["AA → R10","AA → BB"]),field("f2","Frame VLAN20",["R20 → BB","R10 → BB"]),field("ip","IPv4 Destination")],"correct_map":{"f1":"aa → r10","f2":"r20 → bb","ip":"192.168.20.30"},"feedback":{"f1":"O primeiro enlace termina no gateway VLAN10.","f2":"O novo frame nasce no contexto VLAN20.","ip":"Sem NAT, o destino IP permanece B."},"misconceptions":{"f1":"assumes_router_reuses_same_ethernet_frame","ip":"assumes_destination_ip_changes_when_crossing_vlan"},"wrong_feedback":"Compare os MACs de cada enlace, mantendo o pacote IP separado.","correct_feedback":"Correto. AA→R10, depois R20→BB; o IP final permanece 192.168.20.30.","hints":[]},
